"""Bind prepared Bundle identities; never compute a separator surface."""
from types import SimpleNamespace
from .curved_junction_bindings import _mesh
from .curved_patch_provider_bindings import owner_sites, values


def bind(preparation, tables, label, *, free_ends=False, direct_sites=False, selection_ends=False):
    if selection_ends and not (free_ends and direct_sites):
        raise ValueError('Selection caps require explicit direct-site external ownership')
    if getattr(preparation,'selection_ended',()) and not selection_ends:
        raise ValueError('Selection-ended separator requires its declared terminal-cap branch')
    if getattr(preparation, 'free_ended', ()) and not free_ends:
        raise ValueError('Free-ended separators require native open-boundary support; the closed binding cannot consume them')
    sites = values(tables['Junctions'], 'st_cj_junction_id')
    if direct_sites:
        if len(set(sites)) != len(sites) or len(tables['Compounds'].vertices):
            raise ValueError('Direct separator owners require distinct, unmerged original sites')
        owners = {(jid,): i for i, jid in enumerate(sites)}
    else:
        owners = {tuple(sorted(sites[i] for i in members)): owner
                  for owner, members in owner_sites({k: SimpleNamespace(data=v) for k, v in tables.items()}).items()}
    rows = []
    for item in preparation.closed:
        if item.head_sites not in owners or item.tail_sites not in owners:
            raise ValueError('Closed separator lost its exact original terminal surface owner')
        rows.append(dict(bundle_id=item.bundle_id, member_a=item.member_street_ids[0],
            member_b=item.member_street_ids[1], head_patch=owners[item.head_sites], tail_patch=owners[item.tail_sites], kind=0))
    for item in getattr(preparation, 'free_ended', ()):
        if item.attached_sites not in owners:
            raise ValueError('Free-ended separator lost its exact attached surface owner')
        rows.append(dict(bundle_id=item.bundle_id, member_a=item.member_street_ids[0],
            member_b=item.member_street_ids[1], head_patch=owners[item.attached_sites], tail_patch=-1, kind=1))
    for item in getattr(preparation,'selection_ended',()):
        if item.attached_sites not in owners:
            raise ValueError('Selection-ended separator lost its original attached owner')
        row=dict(bundle_id=item.bundle_id,member_a=item.member_street_ids[0],
            member_b=item.member_street_ids[1],head_patch=owners[item.attached_sites],tail_patch=-1,kind=5)
        external=tables['External Approaches']
        ids=values(external,'st_ca_street_id')
        for side,sid,end in zip(('a','b'),item.member_street_ids,item.terminal_ends):
            role={'FREE':1,'SELECTION_BOUNDARY':6}.get(end.owner_kind)
            if role is None or end.endpoint.street_id!=sid or end.junction_id is not None or ids.count(sid)!=1:
                raise ValueError('Selection cap needs each exact original external member end')
            index=ids.index(sid);owner=end.endpoint.section_id if role==6 else -1
            if (values(external,'st_ca_end_role')[index],values(external,'st_ca_owner_id')[index],
                values(external,'st_ca_next_section_id')[index])!=(role,owner,-1):
                raise ValueError('Selection cap declaration disagrees with actual external route')
            row['end_role_'+side]=role;row['end_section_'+side]=owner
        if 6 not in (row['end_role_a'],row['end_role_b']):
            raise ValueError('Selection cap must retain at least one declared selection boundary')
        rows.append(row)
    if len({r['bundle_id'] for r in rows}) != len(rows):
        raise ValueError('A Bundle cannot have two separator declarations')
    selected = {sid for item in (*preparation.closed, *getattr(preparation, 'free_ended', ()), *getattr(preparation,'selection_ended',()))
                for sid in item.member_street_ids}
    approaches = tables['Approaches']
    flag = approaches.attributes.get('st_cj_separator_parity') or approaches.attributes.new('st_cj_separator_parity', 'BOOLEAN', 'POINT')
    flag.data.foreach_set('value', [sid in selected for sid in values(approaches, 'st_cj_street_id')])
    return _mesh(label+' private separators', [(0., 0., 0.)]*len(rows), [], [
        ('st_sb_'+key, 'INT', 'POINT', [row.get(key,-1) for row in rows])
        for key in ('bundle_id', 'member_a', 'member_b', 'head_patch', 'tail_patch')+ (('kind',) if free_ends else ())+
        (('end_role_a','end_role_b','end_section_a','end_section_b') if selection_ends else ())])
